window.NATURABLE_PACKS = {"en":{"version":"en-v1.1","language":"en","released":"2026-10-22","changelog":["Initial EN formal pack: hollow -> structure -> assistant -> lexicon; Wikipedia/blader/no-ai-slop patterns deduped.","v1.1: fix positive_negative_parallel (never matched without a comma before \"or\"); add en.structure.dash_dense (thresholds are initial and need calibration)."],"layer_order":["hollow","structure","artifact","lexicon"],"rules":[{"id":"en.hollow.vague_source","name_en":"Vague source","name_zh":"模糊来源","layer":"hollow","category":"evidence","severity":"strong","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":1.4,"social":0.9,"technical":1.2},"detect":{"type":"regex","pattern":"\\b(experts (?:believe|say|agree)|studies (?:show|suggest|indicate)|research (?:shows|suggests)|it is widely (?:believed|known|accepted)|many people believe)\\b","flags":"gi"},"rewrite":"Name the source, date, or remove the attribution.","reason":"The attribution cannot be checked as written.","before":"Experts believe this approach works.","after":"A 2024 NIST brief found this approach works.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#vague-sources"},{"id":"en.hollow.generic_conclusion","name_en":"Generic conclusion","name_zh":"空洞结论","layer":"hollow","category":"evidence","severity":"strong","confidence":"medium","purpose_weights":{"blog":1.1,"email":0.9,"marketing":1.2,"general":1,"academic":1.1,"social":1,"technical":0.8},"detect":{"type":"regex","pattern":"\\b(the future looks bright|the possibilities are endless|only time will tell|the sky['’]s the limit|a brighter tomorrow|transform(?:ing|s)? the way we (?:live|work|think))\\b","flags":"gi"},"rewrite":"End with a specific result, limit, or next step.","reason":"The ending makes a broad claim without evidence or action.","before":"The future looks bright.","after":"Ship the pilot to three teams next quarter.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#generic-conclusions"},{"id":"en.hollow.fake_certainty","name_en":"Fake certainty","name_zh":"空泛断定","layer":"hollow","category":"evidence","severity":"strong","confidence":"medium","purpose_weights":{"blog":1,"email":1,"marketing":1.1,"general":1,"academic":1.2,"social":0.8,"technical":1.1},"detect":{"type":"regex","pattern":"\\b(it is (?:clear|obvious|evident) that|needless to say|without a doubt|there is no doubt that)\\b","flags":"gi"},"rewrite":"State the claim and the evidence; drop the certainty filler.","reason":"Certainty language stands in for missing proof.","before":"It is clear that adoption will rise.","after":"Adoption rose 12% after the pilot.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#fake-certainty"},{"id":"en.hollow.unsourced_everyone","name_en":"Unsourced everyone-claim","name_zh":"无出处全称概括","layer":"hollow","category":"evidence","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.9,"marketing":1.1,"general":1,"academic":1.3,"social":0.8,"technical":1},"detect":{"type":"regex","pattern":"\\b(everyone knows that|as we all know|in today['’]s (?:fast-paced|ever-changing) world)\\b","flags":"gi"},"rewrite":"Drop the chorus claim; open with the concrete point.","reason":"Appeals to an unnamed consensus instead of a fact.","before":"As we all know, speed matters.","after":"Speed matters when checkout takes over three seconds.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#template-openers"},{"id":"en.hollow.specificity_cover","name_en":"Specificity cover-up risk","name_zh":"概括盖住已有数字","layer":"hollow","category":"evidence","severity":"strong","confidence":"high","purpose_weights":{"blog":1.2,"email":1.1,"marketing":1.3,"general":1.1,"academic":1.4,"social":1,"technical":1.3},"detect":{"type":"heuristic","name":"specificity_cover"},"rewrite":"Keep the numbers and names already in the draft; do not replace them with empty summary.","reason":"A hollow summary sits next to concrete figures that should stay visible.","before":"Revenue hit $4.2M. Experts believe growth is strong.","after":"Revenue hit $4.2M, up 18% year over year.","auto":false,"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/how-it-works/#rule-en-hollow-specificity_cover"},{"id":"en.structure.not_just_but","name_en":"Not-just / but frame","name_zh":"翻案腔（英文）","layer":"structure","category":"sentence","severity":"strong","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":0.9,"social":1.1,"technical":0.8},"detect":{"type":"regex","pattern":"\\b(?:it['’]s|it is|this is|that is|is) not (?:just|only|about)\\b[^.!?]{0,120}?\\b(?:it['’]s|it is)\\b","flags":"gi"},"rewrite":"State the main claim directly without the fake contrast.","reason":"The 'not just X, it is Y' frame often sounds rehearsed.","before":"This technology is not just a tool, it's a pivotal shift.","after":"The change cuts review time in half.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#not-just-frame"},{"id":"en.structure.colon_throat","name_en":"Colon throat-clearing","name_zh":"冒号空转引导","layer":"structure","category":"structure","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":0.8,"social":1,"technical":0.9},"detect":{"type":"regex","pattern":"\\b((?:here['’]s|here is) what you need to know|the (?:key|bottom line|truth) is this|consider the following)\\s*:","flags":"gi"},"rewrite":"Delete the empty lead-in; keep the content after the colon.","reason":"The phrase announces content instead of delivering it.","before":"Here's what you need to know: ship weekly.","after":"Ship weekly.","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#throat-clearing"},{"id":"en.structure.list_intro_empty","name_en":"Empty list intro","name_zh":"空转列表引导","layer":"structure","category":"structure","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":0.7,"social":0.9,"technical":0.8},"detect":{"type":"regex","pattern":"\\b(there are (?:several|many|numerous) (?:benefits|reasons|ways|factors|things)|the (?:benefits|advantages) (?:are|include) (?:numerous|many))\\b[^.!?]{0,40}:","flags":"gi"},"rewrite":"Remove the empty intro; keep the list items intact.","reason":"A throat-clearing sentence adds no information before a list.","before":"There are several benefits:","after":"(keep the list; drop the intro)","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#throat-clearing"},{"id":"en.structure.signpost","name_en":"Formulaic signpost","name_zh":"公式化路标","layer":"structure","category":"structure","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.2,"email":0.9,"marketing":1.3,"general":1,"academic":0.7,"social":1.1,"technical":0.6},"detect":{"type":"regex","pattern":"\\b(let['’]s dive in|without further ado|in today['’]s (?:world|landscape|digital (?:age|landscape|world))|at the end of the day)\\b","flags":"gi"},"rewrite":"Begin with the concrete point.","reason":"The opening announces content instead of delivering it.","before":"In today's digital landscape, teams ship faster.","after":"Teams ship faster when reviews finish same-day.","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#template-openers"},{"id":"en.structure.adjacent_parallel","name_en":"Adjacent parallel sentences","name_zh":"邻句同构","layer":"structure","category":"rhythm","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":0.9,"social":1,"technical":0.8},"detect":{"type":"heuristic","name":"adjacent_parallel"},"rewrite":"Vary openings and sentence shape; keep the facts.","reason":"Neighboring sentences share the same template.","before":"It improves speed. It improves quality. It improves trust.","after":"It improves speed. Quality follows when reviews shrink. Trust rises when numbers stay visible.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#same-shape-sentences"},{"id":"en.structure.rule_of_three_slogans","name_en":"Empty rule-of-three slogan","name_zh":"空转三项排比","layer":"structure","category":"sentence","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.8,"marketing":1.3,"general":1,"academic":0.6,"social":1.1,"technical":0.5},"detect":{"type":"regex","pattern":"\\b(better|faster|stronger|smarter|simpler),\\s+(better|faster|stronger|smarter|simpler),\\s+and\\s+(better|faster|stronger|smarter|simpler)\\b","flags":"gi"},"rewrite":"Replace the slogan triad with one measurable claim.","reason":"Three vague adjectives read like marketing filler.","before":"Better, faster, and stronger results await.","after":"Median review time dropped from 4 days to 1.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/how-it-works/#rule-en-structure-rule_of_three_slogans"},{"id":"en.structure.in_conclusion","name_en":"Stock conclusion opener","name_zh":"套话收尾引导","layer":"structure","category":"structure","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1,"email":0.8,"marketing":1,"general":1,"academic":0.7,"social":0.9,"technical":0.7},"detect":{"type":"regex","pattern":"\\b(in conclusion|to (?:summarize|sum up|conclude)|all in all|in summary)\\b[,:]?","flags":"gi"},"rewrite":"Delete the stock opener; keep the closing point.","reason":"The phrase signals a template ending.","before":"In conclusion, ship the smaller release first.","after":"Ship the smaller release first.","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#generic-conclusions"},{"id":"en.structure.dash_dense","name_en":"Dense em dashes","name_zh":"破折号过密（英文）","layer":"structure","category":"rhythm","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":1,"marketing":1,"general":1,"academic":0.8,"social":1,"technical":0.8},"detect":{"type":"heuristic","name":"en_dash_dense","params":{"min_count":3,"per_1000_words":8}},"rewrite":"Swap some dashes for a comma, period, colon or parentheses. Keep the ones doing real work.","reason":"Frequent em dashes are a common chatbot habit. A few are fine; a steady stream reads as a template.","before":"The plan — including the dates — is ready — and approved.","after":"The plan, including the dates, is ready and approved.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#em-dashes"},{"id":"en.structure.positive_negative_parallel","name_en":"Whether-or parallelism","name_zh":"是否对称排比","layer":"structure","category":"sentence","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.9,"marketing":1.1,"general":1,"academic":0.8,"social":1,"technical":0.7},"detect":{"type":"regex","pattern":"\\bwhether (?:you['’]re|it['’]s|you are|it is) [^.!?]{3,60}?,? or [^.!?]{3,60}?,\\s*(?:this|it|that) (?:is|can be|remains|will be)","flags":"gi"},"rewrite":"Pick the relevant case; drop the mirrored fork.","reason":"Mirrored whether/or frames often pad a thin claim.","before":"Whether you're a beginner or an expert, this is essential.","after":"New editors should learn the shortcut first.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/how-it-works/#rule-en-structure-positive_negative_parallel"},{"id":"en.artifact.chat","name_en":"Assistant chatter","name_zh":"助手寒暄","layer":"artifact","category":"artifact","severity":"strong","confidence":"high","purpose_weights":{"blog":1.3,"email":1.2,"marketing":1.3,"general":1.2,"academic":1.4,"social":1.1,"technical":1.3},"detect":{"type":"regex","pattern":"\\b(Great question[!.]?|I hope this helps[!.]?|let me know if[^.!?]*|feel free to (?:ask|reach out)[^.!?]*|I['’]d be happy to help[^.!?]*)","flags":"gi"},"rewrite":"Delete the aside and address the reader directly.","reason":"Leftover assistant phrasing distracts from the document.","before":"Great question! Ship weekly.","after":"Ship weekly.","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#assistant-leftovers"},{"id":"en.artifact.disclaimer","name_en":"Model disclaimer","name_zh":"模型免责声明","layer":"artifact","category":"artifact","severity":"strong","confidence":"high","purpose_weights":{"blog":1.3,"email":1.2,"marketing":1.2,"general":1.2,"academic":1.4,"social":1.1,"technical":1.3},"detect":{"type":"regex","pattern":"\\b(as of my last (?:update|knowledge cutoff)|based on the available sources|information may be incomplete|as an AI(?: language)? model[^.!]*)\\b","flags":"gi"},"rewrite":"Verify the claim or remove the disclaimer.","reason":"This reads like a model limitation rather than document content.","before":"As of my last update, the API supports streaming.","after":"The API supports streaming as of March 2026.","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#model-disclaimers"},{"id":"en.artifact.let_me","name_en":"Assistant scaffolding","name_zh":"助手脚手架","layer":"artifact","category":"artifact","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.1,"general":1,"academic":1.2,"social":0.9,"technical":1},"detect":{"type":"regex","pattern":"\\b(let me (?:explain|break (?:this|it) down|walk you through)|here['’]s a (?:quick )?(?:overview|summary) of)\\b","flags":"gi"},"rewrite":"Drop the scaffolding; start with the content.","reason":"Assistant staging language is not part of the document voice.","before":"Let me explain: we ship on Fridays.","after":"We ship on Fridays.","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/how-it-works/#rule-en-artifact-let_me"},{"id":"en.lexicon.filler_phrase","name_en":"Wordy filler phrase","name_zh":"冗长填充语","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1,"email":1.1,"marketing":1,"general":1,"academic":0.7,"social":1,"technical":0.9},"detect":{"type":"regex","pattern":"\\b(in order to|due to the fact that|it is important to note that|it is worth noting that|for all intents and purposes)\\b","flags":"gi"},"rewrite":"Use the shorter alternative.","reason":"The phrase adds length without useful meaning.","before":"In order to finish, cut scope.","after":"To finish, cut scope.","auto":true,"fix":{"type":"map","map":{"in order to":"to","due to the fact that":"because","it is important to note that":"","it is worth noting that":"","for all intents and purposes":"essentially"}},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#filler-phrases"},{"id":"en.lexicon.cliche","name_en":"Generic AI diction","name_zh":"泛化 AI 用词","layer":"lexicon","category":"vocabulary","severity":"strong","confidence":"medium","purpose_weights":{"blog":1.1,"email":1,"marketing":0.8,"general":1,"academic":0.5,"social":1,"technical":0.7},"detect":{"type":"regex","pattern":"\\b(delve|tapestry|realm|showcas(?:e|ing)|leverage|myriad|plethora|seamless(?:ly)?|robust|pivotal|foster(?:ing)?|embark|elevate|harness(?:ing)?|underscore(?:s|d|ing)? the importance|landscape|nestled|boasts)\\b","flags":"gi"},"rewrite":"Replace it with a plain, precise word.","reason":"This wording is common in polished but nonspecific drafts.","before":"We leverage a robust solution.","after":"We use Postgres with read replicas.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/ai-words-to-avoid/#top-words"},{"id":"en.lexicon.transition_stack","name_en":"Stock transition opener","name_zh":"套话转折开篇","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.1,"general":1,"academic":0.6,"social":1,"technical":0.7},"detect":{"type":"regex","pattern":"(^|[.!?\\n]\\s*)(Furthermore|Moreover|Additionally|In addition|Consequently|Hence|Thus|Therefore)\\b","flags":"gim"},"rewrite":"Delete or replace with a plain connective that fits the logic.","reason":"Sentence-initial stock transitions often mark assistant cadence.","before":"Furthermore, costs fell.","after":"Costs fell.","auto":true,"fix":{"type":"replace_match","strip":true},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#transition-openers"},{"id":"en.lexicon.hedge_stack","name_en":"Stacked hedging","name_zh":"对冲词堆叠","layer":"lexicon","category":"sentence","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":1,"marketing":1.1,"general":1,"academic":0.6,"social":0.9,"technical":0.8},"detect":{"type":"regex","pattern":"\\b(could potentially|may possibly|it (?:could|might) be argued that|tends to somewhat)\\b","flags":"gi"},"rewrite":"Keep one qualifier and state the evidence.","reason":"Multiple qualifiers make the claim vague.","before":"Teams could potentially rethink their work.","after":"Teams may rethink their work after the pilot.","auto":true,"fix":{"type":"map","map":{"could potentially":"could","may possibly":"may","it could be argued that":"","it might be argued that":"","tends to somewhat":"tends to"}},"evidence_policy":"keep_numbers","docs":"https://naturable.app/en/signs-of-ai-writing/#stacked-hedges"},{"id":"en.lexicon.play_role","name_en":"Play a role filler","name_zh":"发挥作用套话","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.9,"marketing":1.1,"general":1,"academic":0.7,"social":0.9,"technical":0.8},"detect":{"type":"regex","pattern":"\\b(play(?:s|ed|ing)? a (?:vital|important|key|crucial) role|serves? as a testament to)\\b","flags":"gi"},"rewrite":"Say what the subject actually does.","reason":"The idiom asserts importance without describing the action.","before":"Caching plays a vital role in latency.","after":"Caching cuts p95 latency by 40%.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#role-and-journey"},{"id":"en.lexicon.journey_unlock","name_en":"Journey / unlock cliche","name_zh":"旅程解锁套话","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.1,"email":0.9,"marketing":0.9,"general":1,"academic":0.5,"social":1.1,"technical":0.6},"detect":{"type":"regex","pattern":"\\b(embark(?:s|ed|ing)? on a (?:journey|quest)|unlock(?:s|ed|ing)? the (?:full )?potential|game-?changer)\\b","flags":"gi"},"rewrite":"Name the concrete change.","reason":"Motivational cliches hide the actual mechanism.","before":"This unlocks the full potential of the team.","after":"This frees two engineers from weekly triage.","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/en/signs-of-ai-writing/#role-and-journey"}]},"zh":{"version":"zh-v1.1","language":"zh","released":"2026-10-22","beta":true,"changelog":["ZH Beta: only 11 validated classes from 283-wan-zi study; banned 少用比喻/删除设问/句长必须不均匀/硬补就.","v1.1: de_stack example had only two 的 and could never trigger the 3+ rule; example corrected, pattern unchanged."],"layer_order":["hollow","structure","artifact","lexicon"],"banned_rules":[{"id":"zh.banned.less_metaphor","label":"少用比喻","reason":"Humans use more metaphors; problem is persona type, not metaphor count."},{"id":"zh.banned.delete_rhetorical","label":"删除设问","reason":"Removing rhetorical questions makes text less human."},{"id":"zh.banned.force_uneven_length","label":"句长必须不均匀","reason":"No difference after corrected segmentation."},{"id":"zh.banned.force_jiu","label":"硬补就","reason":"Directionally plausible but not productizable."}],"class_ids":["zh.para.zero_anaphora","zh.metaphor.ideal_persona","zh.colon.list_intro","zh.colon.prompt","zh.flip.not_but","zh.opener.filler","zh.ordinal.fake_heading","zh.dash.dense","zh.adjacent.parallel","zh.enumeration.dense","zh.translationese"],"rules":[{"id":"zh.para.zero_anaphora","class_id":"zh.para.zero_anaphora","name_en":"Paragraph-start zero anaphora comment","name_zh":"段首零回指评论","layer":"structure","category":"structure","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.2,"email":1,"marketing":1.1,"general":1,"academic":0.9,"social":1,"technical":0.8},"detect":{"type":"heuristic","name":"zh_zero_anaphora"},"rewrite":"在段首评价前补上“这/该…”回指，或并入上段。","reason":"段首直接下评价却缺少回指，读起来像模板评论。","before":"值得肯定。产品节奏更快了。","after":"这一点值得肯定：产品节奏更快了。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.metaphor.ideal_persona","class_id":"zh.metaphor.ideal_persona","name_en":"Ideal-persona metaphor","name_zh":"拟人化理想人格喻体","layer":"hollow","category":"vocabulary","severity":"strong","confidence":"high","purpose_weights":{"blog":1.2,"email":1,"marketing":1.3,"general":1.1,"academic":1,"social":1.1,"technical":0.9},"detect":{"type":"regex","pattern":"(智慧的导师|不知疲倦的助手|贴心的伙伴|忠诚的卫士|沉默的守望者|智能助手就像[^。！？]{0,20}老师)","flags":"g"},"rewrite":"换成具体的人或删掉喻体，只保留实际作用。","reason":"理想人格式喻体是中文 AI 稿常见空洞修辞。","before":"它像一位智慧的导师，指引方向。","after":"值班工程师会在告警后15分钟内接手。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.colon.list_intro","class_id":"zh.colon.list_intro","name_en":"Empty colon list intro","name_zh":"冒号滥用·空转句引列表","layer":"structure","category":"structure","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":0.8,"social":0.9,"technical":0.9},"detect":{"type":"regex","pattern":"(具体(?:来说|而言)|主要包括|有以下几点|可以从以下几个方面|包括以下几点)[:：]","flags":"g"},"rewrite":"删掉空转引导，保留列表内容与顺序。","reason":"空转引导句不增加信息，只是在引列表。","before":"具体来说：成本下降，速度提升。","after":"成本下降，速度提升。","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.colon.prompt","class_id":"zh.colon.prompt","name_en":"Colon prompt filler","name_zh":"冒号滥用·提示语","layer":"structure","category":"structure","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.1,"general":1,"academic":0.8,"social":1,"technical":0.9},"detect":{"type":"regex","pattern":"(核心是|关键在于|重点是|本质上是|简单说就是)[:：]","flags":"g"},"rewrite":"删掉提示语，直接写后面的内容。","reason":"冒号前的提示语常是助手腔脚手架。","before":"核心是：把评审时间压到一天内。","after":"把评审时间压到一天内。","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.flip.not_but","class_id":"zh.flip.not_but","name_en":"Not-A-but-B flip","name_zh":"翻案腔（不是……而是……）","layer":"structure","category":"sentence","severity":"strong","confidence":"high","purpose_weights":{"blog":1.2,"email":1.1,"marketing":1.3,"general":1.1,"academic":0.9,"social":1.2,"technical":0.8},"detect":{"type":"regex","pattern":"不是[^。！？；]{1,30}而是[^。！？；]{1,40}","flags":"g"},"rewrite":"去掉假对立，直接陈述主判断。","reason":"假对立翻案腔是中文 AI 稿高频结构。","before":"这不是工具问题，而是流程问题。","after":"评审排队拖慢了发布。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.opener.filler","class_id":"zh.opener.filler","name_en":"Opener filler","name_zh":"起首语填充","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"high","purpose_weights":{"blog":1.1,"email":1,"marketing":1.1,"general":1,"academic":0.8,"social":1,"technical":0.9},"detect":{"type":"regex","pattern":"(说白了|简单来说|总的来说|值得一提的是|不可否认的是|毋庸置疑的是|需要指出的是)","flags":"g"},"rewrite":"删除起首语，或改写成带判断的完整句。","reason":"起首填充语常可直接删掉而不损失信息。","before":"说白了，成本已经下降。","after":"成本已经下降。","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.ordinal.fake_heading","class_id":"zh.ordinal.fake_heading","name_en":"Ordinals as fake headings","name_zh":"序数词当小标题","layer":"structure","category":"structure","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.1,"email":0.9,"marketing":1.2,"general":1,"academic":0.7,"social":0.9,"technical":0.8},"detect":{"type":"regex","pattern":"(?:^|[\\n。；])\\s*(第[一二三四五六七八九十1-9]|首先|其次|再次|最后)[，,、]","flags":"gm"},"rewrite":"降为正文衔接，或改成真正的小标题，避免假目录感。","reason":"连续序数开段会造成模板提纲感。","before":"首先，提升效率。其次，降低成本。","after":"效率先提升；成本也会跟着下降。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.dash.dense","class_id":"zh.dash.dense","name_en":"Dense dash usage","name_zh":"破折号过密","layer":"structure","category":"rhythm","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.9,"marketing":1,"general":1,"academic":0.8,"social":1,"technical":0.8},"detect":{"type":"heuristic","name":"zh_dash_dense"},"rewrite":"降低破折号密度；能用逗号或句号处优先改写。注意：部分模型更爱用破折号，这不是作者判决。","reason":"破折号过密会形成可辨认的模型痕迹（Claude/DeepSeek 更重）。","before":"方案——包括排期——已经——确认。","after":"方案（含排期）已经确认。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.adjacent.parallel","class_id":"zh.adjacent.parallel","name_en":"Adjacent parallel structure","name_zh":"相邻句结构同款","layer":"structure","category":"rhythm","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1.1,"email":1,"marketing":1.2,"general":1,"academic":0.9,"social":1,"technical":0.8},"detect":{"type":"heuristic","name":"zh_adjacent_parallel"},"rewrite":"拆开同构，让句式跟着信息变化。","reason":"相邻句同一模板是中文 AI 稿常见结构问题。","before":"它提升了效率。它降低了成本。它改善了体验。","after":"效率先上去；成本随批量下降。体验则来自更短的等待。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.enumeration.dense","class_id":"zh.enumeration.dense","name_en":"Dense enumeration pauses","name_zh":"顿号罗列过密","layer":"structure","category":"sentence","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.9,"marketing":1.1,"general":1,"academic":0.8,"social":0.9,"technical":0.9},"detect":{"type":"heuristic","name":"zh_enumeration_dense"},"rewrite":"拆成短句，或删掉弱项，避免一长串顿号堆叠。","reason":"顿号过密会让信息变成清单而不是论述。","before":"涵盖效率、质量、体验、成本、安全、合规、扩展。","after":"先看效率与质量；成本、安全另开一节。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.translationese.passive","class_id":"zh.translationese","name_en":"Translationese passive","name_zh":"翻译腔·被动堆叠","layer":"lexicon","category":"sentence","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":1,"marketing":1,"general":1,"academic":0.8,"social":0.9,"technical":0.9},"detect":{"type":"regex","pattern":"(被[^。！？]{0,8}所[^。！？]{1,12}|被进行|被予以)","flags":"g"},"rewrite":"改成主动表述，说明谁做了什么。","reason":"欧化被动是翻译腔子类之一。","before":"方案被团队所认可。","after":"团队认可了这套方案。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.translationese.de_stack","class_id":"zh.translationese","name_en":"Translationese 的-stack","name_zh":"翻译腔·的字链","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":1,"marketing":1,"general":1,"academic":0.9,"social":0.9,"technical":0.9},"detect":{"type":"regex","pattern":"([\\u4e00-\\u9fff]{1,6}的){3,}[\\u4e00-\\u9fff]{1,8}","flags":"g"},"rewrite":"打断“的”字链，改成短句或动词结构。","reason":"连续“的”字链是翻译腔常见表面特征。","before":"这是我们团队的非常重要的需要重视的问题。","after":"这个问题需要认真对待。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.translationese.men","class_id":"zh.translationese","name_en":"Translationese 们 abuse","name_zh":"翻译腔·们字滥用","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":0.9,"email":0.9,"marketing":1,"general":1,"academic":0.8,"social":0.9,"technical":0.8},"detect":{"type":"regex","pattern":"(用户们|读者们|开发者们|人们们)","flags":"g"},"rewrite":"中文复数常可省略“们”，或改成具体群体名。","reason":"不必要的“们”常来自英文复数直译。","before":"用户们可以导出结果。","after":"用户可以导出结果。","auto":true,"fix":{"type":"map","map":{"用户们":"用户","读者们":"读者","开发者们":"开发者","人们们":"人们"}},"evidence_policy":"keep_numbers","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.translationese.ongoing","class_id":"zh.translationese","name_en":"Translationese progressive padding","name_zh":"翻译腔·进行时垫话","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":1,"marketing":1,"general":1,"academic":0.8,"social":0.9,"technical":0.9},"detect":{"type":"regex","pattern":"(正在进行着?|进行一个|做出一个[^。！？]{0,6}的?(?:决定|选择|改变))","flags":"g"},"rewrite":"删掉进行时垫话，直接用动词。","reason":"进行时垫话多来自英文进行体直译。","before":"我们正在进行着评估。","after":"我们在评估。","auto":true,"fix":{"type":"map","map":{"正在进行着":"在","正在进行":"在"}},"evidence_policy":"keep_numbers","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.translationese.one_of","class_id":"zh.translationese","name_en":"Translationese one-of stack","name_zh":"翻译腔·之一堆叠","layer":"lexicon","category":"vocabulary","severity":"suggestion","confidence":"medium","purpose_weights":{"blog":1,"email":0.9,"marketing":1.1,"general":1,"academic":0.8,"social":1,"technical":0.8},"detect":{"type":"regex","pattern":"(最[^。！？]{0,8}之一|之一[^。！？]{0,6}之一)","flags":"g"},"rewrite":"能说程度就说程度，避免空洞“之一”。","reason":"“最…之一”常是英文 one of the 直译垫话。","before":"这是最重要的挑战之一。","after":"这是眼下最紧的挑战。","auto":false,"evidence_policy":"never_invent","docs":"https://naturable.app/zh-cn/how-it-works/"},{"id":"zh.artifact.chat","name_en":"ZH assistant chatter","name_zh":"助手寒暄","layer":"artifact","category":"artifact","severity":"strong","confidence":"high","purpose_weights":{"blog":1.3,"email":1.2,"marketing":1.3,"general":1.2,"academic":1.4,"social":1.1,"technical":1.3},"detect":{"type":"regex","pattern":"(很高兴为你解答[！!]?|希望这对你有所帮助[！!]?|如果你还有任何问题[^。！？!?]*)","flags":"g"},"rewrite":"删除寒暄，直接进入内容。","reason":"这是对话助手残留，不属于正文。","before":"希望这对你有所帮助！成本已下降。","after":"成本已下降。","auto":true,"fix":{"type":"delete"},"evidence_policy":"keep_numbers","docs":"https://naturable.app/zh-cn/how-it-works/"}]},"meta":{"engine_pack_api":1,"default_en":"en-v1.1","default_zh":"zh-v1.1"}};
